const SC = window.SugarCube;
const story = SC.Story;
const passages = Object.keys(story.lookup ? story.lookup('tags', '') : {}).slice(0,5);
// Get all passage names that look like locations or hubs
const all = [];
if (story.passages) {
  for (const k of Object.keys(story.passages)) {
    if (/loc_|free.?roam|location|hub|hallway/i.test(k)) all.push(k);
  }
}
return JSON.stringify({passages_count: Object.keys(story.passages || {}).length, location_like: all.slice(0,30)}, null, 2);

const SC = window.SugarCube;
// Set state to post-bookkeeping-offer (no catch yet)
const v = SC.State.variables;
v.flags.frank_offered_bookkeeping = true;
v.flags.arrived_at_franks = true;
// Navigate to Frank's Office to test the office hub
// First, set Maya's corruption to 0 just to be clean
v.player.core_traits.corruption = 0;
// Force time to evening when office is open (19:00-21:30) and weekday
// Find Frank NPC by slug
const npcs = v.npcs || {};
let frankId = null;
for (const id of Object.keys(npcs)) {
  if (npcs[id] && npcs[id].slug === 'npc_frank') { frankId = id; break; }
}
// Find game time + day controls
return JSON.stringify({
  game_state: v.game_state,
  frank_id: frankId,
  frank_node: frankId ? npcs[frankId] : null,
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
// Inspect NPC structure
const npcs = v.npcs || {};
const frankEntry = Object.entries(npcs).find(([id, npc]) => 
  npc && (npc.name === 'Frank' || (npc.name||'').toLowerCase().includes('frank'))
);
return JSON.stringify({
  npc_count: Object.keys(npcs).length,
  sample_npc_keys: Object.keys(Object.values(npcs)[0] || {}),
  sample_npc: Object.values(npcs)[0],
  frank_found: frankEntry ? frankEntry[0] : null,
  frank: frankEntry ? frankEntry[1] : null,
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
// POST-CATCH state: caught + restrict_declared, NOT cracked yet
v.flags.frank_offered_bookkeeping = true;
v.flags.frank_caught = true;
v.flags.frank_restrict_declared = true;
v.flags.frank_cracked = false;
v.flags.arrived_at_franks = true;
v.flags.frank_supervision_explained = false;  // Allow supervision intro to fire
v.player.core_traits.corruption = 30;
// Set time to evening Tuesday (weekday 19:00)
v.game_state.time_state.current_hour = 19;
v.game_state.time_state.current_minute = 30;
v.game_state.time_state.current_day = 'Tuesday';
v.game_state.time_state.day = 2;
// Frank traits to support office content
const npcs = v.npcs;
for (const id of Object.keys(npcs)) {
  if (npcs[id] && npcs[id].name === 'Frank') {
    npcs[id].core_traits.trust = 20;
    npcs[id].core_traits.arousal = 5;
    npcs[id].core_traits.corruption = 5;
  }
}
return 'state set';

